from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[1]
html=(R/'qa-autoplay.html').read_text()
# qa-autoplay.html regenerated by autoplay_browser_qa.py, which also runs a full test.
results=[]
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,executable_path='/usr/bin/chromium',args=['--no-sandbox','--disable-dev-shm-usage'])
 for i in range(16):
  width,height= [(844,390),(1024,768),(1180,664),(960,540)][i%4]
  page=b.new_page(viewport={'width':width,'height':height},has_touch=True,is_mobile=True)
  errs=[];page.on('pageerror',lambda e:errs.append(str(e)))
  page.set_content(html,wait_until='load');page.locator('#primary').click()
  result=page.evaluate('()=>window.__qa.advance(120)')
  results.append({'run':i+1,'screen':f'{width}x{height}','time':round(result['elapsed'],2),'hp':result['hp'],'state':result['state'],'speed':round(result['speed']),'errors':errs})
  page.close()
 b.close()
print('RESULTS',results)
print('PASSED',sum(x['state']=='running' and x['hp']==3 and not x['errors'] for x in results),'/',len(results))
